template:
fn doubled(values: &[i32]) -> Vec<i32> {
    let mut out = Vec::new();
    for ⟦pat⟧ in values {
        out.push(⟦expr⟧);
    }
    out
}

fn main() {
    println!("{:?}", doubled(&[1, 2, 3]));
}

tests:
#[test]
fn doubles_all() {
    assert_eq!(doubled(&[1, 2, 3]), vec![2, 4, 6]);
    assert_eq!(doubled(&[]), Vec::<i32>::new());
}
